{"content": "1|/**
2| * PINT AE Schematron validation.
3| *
4| * Wraps SaxonJS to run the two official PINT AE pre-compiled XSLT 3.0
5| * stylesheets (exported as .sef.json) against raw UBL XML input.
6| *
7| * The two stylesheets implement:
8| *   1. PINT-UBL-validation-preprocessed  — ~81 IBR rules (mandatory fields,
9| *      code-list membership, GLN checksums, date format)
10| *   2. PINT-jurisdiction-aligned-rules   — ~100 UAE-specific rules (legal
11| *      registration ID types, passport country codes, emirate subdivisions,
12| *      transaction type flags, exchange rate precision)
13| *
14| * Each assertion failure produces an error in the engine's canonical format
15| * with a "SCH/" prefix on the rule ID to distinguish from semantic rules.
16| */
17|
18|import { XMLParser } from 'fast-xml-parser';
19|import { fileURLToPath } from 'url';
20|import { dirname, join, resolve } from 'path';
21|import { existsSync } from 'fs';
22|
23|const __filename = fileURLToPath(import.meta.url);
24|const __dirname = dirname(__filename);
25|
26|// Resolve the pint-ae resource directory relative to this module.
27|// Development: <project>/app/api/ -> <project>/app/api/pint-ae/
28|// Docker: /app/pint-ae/
29|const PINT_AE_DIR = resolve(__dirname, '..', '..', '..', 'pint-ae');
30|const SCH_DIR = join(PINT_AE_DIR, 'trn-invoice', 'schematron');
31|
32|const SEF_FILES = {
33|  preprocessed: join(SCH_DIR, 'PINT-UBL-validation-preprocessed.sef.json'),
34|  jurisdiction: join(SCH_DIR, 'PINT-jurisdiction-aligned-rules.sef.json'),
35|};
36|
37|// Namespace-agnostic SVRL parser config
38|const svrlParser = new XMLParser({
39|  ignoreAttributes: false,
40|  attributeNamePrefix: '@_',
41|  removeNSPrefix: true,
42|  parseTagValue: true,
43|  trimValues: true,
44|  isArray: (tagName) =>
45|    ['fired-rule', 'failed-assert', 'successful-report', 'active-pattern'].includes(tagName),
46|});
47|
48|/**
49| * Check whether the SEF files exist on disk (lazy — called once).
50| * @returns {boolean}
51| */
52|function sefFilesExist() {
53|  return existsSync(SEF_FILES.preprocessed) && existsSync(SEF_FILES.jurisdiction);
54|}
55|
56|/**
57| * Parse an SVRL XML string into an array of assertion-failure descriptors.
58| *
59| * @param {string} svrlXml
60| * @returns {{ id: string, flag: string, location: string, text: string }[]}
61| */
62|function parseSvrlAssertions(svrlXml) {
63|  if (!svrlXml || !svrlXml.trim()) return [];
64|
65|  let tree;
66|  try {
67|    tree = svrlParser.parse(svrlXml);
68|  } catch {
69|    return [];
70|  }
71|
72|  const output = tree['schematron-output'];
73|  if (!output) return [];
74|
75|  const results = [];
76|
77|  // Gather from fired-rule children (common pattern)
78|  const firedRules = output['fired-rule'];
79|  if (firedRules) {
80|    const frList = Array.isArray(firedRules) ? firedRules : [firedRules];
81|    for (const fr of frList) {
82|      const asserts = fr['failed-assert'];
83|      if (!asserts) continue;
84|      const list = Array.isArray(asserts) ? asserts : [asserts];
85|      for (const a of list) {
86|        results.push({
87|          id: a['@_id'] || 'unknown',
88|          flag: a['@_flag'] || 'fatal',
89|          location: a['@_location'] || '/',
90|          text: a['text'] || a['#text'] || '',
91|        });
92|      }
93|    }
94|  }
95|
96|  // Also check top-level failed-assert (some XSLTs may emit them there)
97|  const topAsserts = output['failed-assert'];
98|  if (topAsserts) {
99|    const list = Array.isArray(topAsserts) ? topAsserts : [topAsserts];
100|    for (const a of list) {
101|      // Deduplicate by checking if same id already found
102|      if (!results.some((r) => r.id === a['@_id'])) {
103|        results.push({
104|          id: a['@_id'] || 'unknown',
105|          flag: a['@_flag'] || 'fatal',
106|          location: a['@_location'] || '/',
107|          text: a['text'] || a['#text'] || '',
108|        });
109|      }
110|    }
111|  }
112|
113|  return results;
114|}
115|
116|/**
117| * Run a single XSLT transform via SaxonJS and return the assertion failures.
118| *
119| * @param {string} sefPath  - path to the .sef.json file
120| * @param {string} xmlString - raw UBL XML
121| * @returns {Promise<Array<{ id, flag, location, text }>>}
122| */
123|async function runSchematronXslt(sefPath, xmlString) {
124|  let SaxonJS;
125|  try {
126|    SaxonJS = (await import('saxon-js')).default;
127|  } catch {
128|    // saxon-js not available (e.g. web bundle without it)
129|    return [];
130|  }
131|
132|  let resultXml;
133|  try {
134|    const result = await SaxonJS.transform({
135|      stylesheetLocation: sefPath,
136|      sourceText: xmlString,
137|      destination: 'serialized',
138|    });
139|    resultXml = result.principalResult;
140|  } catch (err) {
141|    // Transform failure — return a synthetic error so the caller knows
142|    // schematron couldn't run.
143|    return [
144|      {
145|        id: 'SCH-INTERNAL',
146|        flag: 'fatal',
147|        location: '/',
148|        text: `Schematron transform failed: ${err instanceof Error ? err.message : String(err)}`,
149|      },
150|    ];
151|  }
152|
153|  return parseSvrlAssertions(resultXml);
154|}
155|
156|/**
157| * Validate an XML invoice string against both PINT AE Schematron rule sets.
158| *
159| * @param {string} xmlString - Raw UBL/PINT AE XML string
160| * @returns {Promise<Array<{ path: string, rule: string, severity: string, message: string, fix: string }>>}
161| */
162|export async function validateSchematron(xmlString) {
163|  if (!xmlString || typeof xmlString !== 'string') {
164|    return [];
165|  }
166|
167|  // If SEF files don't exist (development without full setup, or web bundle),
168|  // skip schematron silently.
169|  if (!sefFilesExist()) {
170|    return [];
171|  }
172|
173|  const allAssertions = [];
174|
175|  // Run preprocessed (IBR) rules
176|  const ibrResults = await runSchematronXslt(SEF_FILES.preprocessed, xmlString);
177|  allAssertions.push(...ibrResults);
178|
179|  // Run jurisdiction-aligned (UAE-specific) rules
180|  const jurResults = await runSchematronXslt(SEF_FILES.jurisdiction, xmlString);
181|  allAssertions.push(...jurResults);
182|
183|  // Map to canonical error format
184|  const errors = [];
185|  const seen = new Set();
186|
187|  for (const a of allAssertions) {
188|    if (!a.id || a.id === 'SCH-INTERNAL') {
189|      // Internal errors are always included
190|    } else {
191|      // Deduplicate by rule id — same rule may fire multiple times for
192|      // the same location, but we report once per rule.
193|      const dedupKey = `${a.id}:${a.location}`;
194|      if (seen.has(dedupKey)) continue;
195|      seen.add(dedupKey);
196|    }
197|
198|    const ruleId = a.id ? `SCH/${a.id.toUpperCase()}` : 'SCH/UNKNOWN';
199|    const severity = a.flag === 'fatal' ? 'error' : 'warning';
200|
201|    // Clean the message text — remove the leading [id]- prefix if present
202|    // since we already have the rule ID separately.
203|    let message = a.text || `Schematron rule ${a.id} failed`;
204|    const idPrefix = a.id ? `[${a.id}]-` : '';
205|    if (idPrefix && message.startsWith(idPrefix)) {
206|      message = message.slice(idPrefix.length).trim();
207|    }
208|
209|    // Map the XPath location to something useful. For now we use the raw
210|    // XPath expression. A future enhancement could translate to JSON-pointer.
211|    let path = a.location || '/';
212|    if (path === '/') path = '/';
213|
214|    // Generate a remediation hint based on the message content
215|    let fix = 'Review the reported field and correct the value.';
216|    if (message.toLowerCase().includes('must')) {
217|      fix = message.replace(/\.$/, '') + '.';
218|    }
219|
220|    errors.push({
221|      path,
222|      rule: ruleId,
223|      severity,
224|      message,
225|      fix,
226|    });
227|  }
228|
229|  return errors;
230|}
231|
232|/**
233| * Detect whether schematron validation produced a fatal error that should
234| * short-circuit semantic validation.
235| *
236| * @param {Array} errors - Array from validateSchematron()
237| * @returns {boolean}
238| */
239|export function hasFatalSchematronError(errors) {
240|  return errors.some((e) => e.severity === 'error' && e.rule.startsWith('SCH/'));
241|}
