6|export const SCHEMA_VERSION_DEFAULT = 'urn:peppol:pint:billing-1@ae-1';
7|export const PARSE_ERROR_RULE = 'ENG-PARSE-01';
8|
9|/**
10| * Run the full preflight validation. Deterministic: same input -> same output.
11| *
12| * When the input is raw UBL XML, the official PINT AE Schematron (XSLT)
13| * stylesheets run as a structural/code-list preflight BEFORE the semantic
14| * rules. If schematron produces fatal errors, the semantic loop is skipped
15| * (no point checking business rules on a structurally invalid invoice).
16| *
17| * @returns {{ valid, invoiceType, schemaVersion, errors }}
18| */
19|export async function validateInvoice(body, contentType = '') {
20|  const { invoice, parseError, rawXml } = normalizeInput(body, contentType);
21|
22|  if (parseError) {
23|    return {
24|      valid: false,
25|      invoiceType: null,
26|      schemaVersion: SCHEMA_VERSION_DEFAULT,
27|      errors: [
28|        {
29|          path: '/',
30|          rule: `${PARSE_ERROR_RULE}`,
31|          severity: 'error',
32|          message: `Could not parse invoice: ${parseError}`,
33|          fix: 'Send a canonical JSON invoice, or a valid UBL 2.1 / PINT AE XML document.',
34|        },
35|      ],
36|    };
37|  }
38|
39|  const errors = [];
40|
41|  // ── Schematron layer (XML only) ──────────────────────────────────────
42|  // Run the official PINT AE XSLT stylesheets. These catch structural
43|  // violations (missing mandatory fields, invalid code lists, format
44|  // checks like GLN checksum, date formats) before semantic rules run.
45|  if (rawXml) {
46|    const schErrors = await validateSchematron(rawXml);
47|    for (const e of schErrors) errors.push(e);
48|
49|    // If schematron found fatal structural errors, skip the semantic loop.
50|    // Semantic rules assume a structurally valid invoice.
51|    if (hasFatalSchematronError(errors)) {
52|      return {
53|        valid: false,
54|        invoiceType: invoice.invoiceType ?? null,
55|        schemaVersion: invoice.schemaVersion || SCHEMA_VERSION_DEFAULT,
56|        errors,
57|      };
58|    }
59|  }
60|
61|  // ── Semantic rule loop ───────────────────────────────────────────────
62|  for (const rule of RULES) {
63|    try {
64|      const produced = rule.evaluate(invoice) || [];
65|      for (const e of produced) errors.push(e);
66|    } catch (e) {
67|      // A rule crash must never take down the request; surface it deterministically.
68|      errors.push({
69|        path: '/',
70|        rule: `${rule.id}/INTERNAL`,
71|        severity: 'error',
72|        message: `Rule ${rule.id} encountered an internal error. Check the field(s) referenced by this rule for malformed values.`,
73|        fix: 'Inspect the reported fields and correct any structurally invalid data.',
74|      });
75|    }
76|  }
77|
78|  const valid = !errors.some((e) => e.severity === 'error');
79|
80|  return {
81|    valid,
82|    invoiceType: invoice.invoiceType ?? null,
83|    schemaVersion: invoice.schemaVersion || SCHEMA_VERSION_DEFAULT,
84|    errors,
85|  };
