=== schematron-bridge.js (new) ===
/**
 * Schematron bridge — lets each service plug its OWN PINT AE Schematron
 * implementation into the shared engine without the package knowing where
 * the vendored assets (.sef.json / .xslt / .gc) live.
 *
 * The official PINT AE conformance gate must run BEFORE the semantic rule
 * loop, and fatal SCH/* errors must short-circuit semantics (hard invariant,
 * see docs/superpowers/plans/2026-08-04-schematron-reconciliation.md §6).
 *
 * Services wire their bridge at startup, e.g.:
 *
 *   import { setSchematronBridge } from '@einvoicecheck/rules';
 *   import { validateSchematron, hasFatalSchematronError } from './schematron.js';
 *   setSchematronBridge({ validateSchematron, hasFatalSchematronError });
 *
 * Until a bridge is installed the engine behaves exactly like the historical
 * web bundle without SEF assets: Schematron is skipped and semantic rules
 * run on their own.
 */

const noopBridge = {
  validateSchematron: async () => [],
  hasFatalSchematronError: () => false,
};

let activeBridge = noopBridge;

/**
 * Install (or clear) the service-local Schematron implementation.
 * @param {{ validateSchematron: Function, hasFatalSchematronError: Function } | null} bridge
 */
export function setSchematronBridge(bridge) {
  activeBridge =
    bridge && typeof bridge.validateSchematron === 'function'
      ? { validateSchematron: bridge.validateSchematron, hasFatalSchematronError: bridge.hasFatalSchematronError || noopBridge.hasFatalSchematronError }
      : noopBridge;
}

/** @returns {{ validateSchematron: Function, hasFatalSchematronError: Function }} */
export function getSchematronBridge() {
  return activeBridge;
}

