{"content": "// hermes-verify-vendored-rules.mjs
// Focused ad-hoc verification for the vendored @einvoicecheck/rules layout:
//   1. Both services' package.json resolve the dep to the LOCAL vendored path (file:packages/rules)
//   2. Both vendored copies exist and are byte-identical (no service drift)
//   3. The old duplicated engine trees are gone (app/api/src/rules, app/web/src/lib/rules)
//   4. Lockfiles reference the new path
//   5. Installed node_modules symlink resolves to the local vendored copy
// This is AD-HOC verification (supplements the green suite runs: app/api 19/19, app/web 115/115).

import { readFile, stat, realpath } from 'node:fs/promises';
import { join } from 'node:path';

const ROOT = 'C:/Users/abdul/https-einvoicecheck.ae';
let failures = 0;
const ok = (name, pass, detail = '') => {
  console.log(`${pass ? 'PASS' : 'FAIL'}  ${name}${detail ? '  — ' + detail : ''}`);
  if (!pass) failures++;
};

// 1. package.json deps point at local vendored path
const apiPkg = JSON.parse(await readFile(join(ROOT, 'app/api/package.json'), 'utf8'));
const webPkg = JSON.parse(await readFile(join(ROOT, 'app/web/package.json'), 'utf8'));
ok('api dep → file:packages/rules', apiPkg.dependencies['@einvoicecheck/rules'] === 'file:packages/rules',
  apiPkg.dependencies['@einvoicecheck/rules']);
ok('web dep → file:packages/rules', webPkg.dependencies['@einvoicecheck/rules'] === 'file:packages/rules',
  webPkg.dependencies['@einvoicecheck/rules']);

// 2. vendored copies exist + byte-identical (engine.js and xml.js are the load-bearing files)
for (const f of ['engine.js', 'xml.js', 'schematron-bridge.js']) {
  const apiPath = join(ROOT, `app/api/packages/rules/src/${f}`);
  const webPath = join(ROOT, `app/web/packages/rules/src/${f}`);
  const [apiSrc, webSrc] = await Promise.all([readFile(apiPath, 'utf8'), readFile(webPath, 'utf8')]);
  ok(`vendored ${f} exists in both`, apiSrc.length > 0 && webSrc.length > 0, `${apiSrc.length}/${webSrc.length} bytes`);
  ok(`vendored ${f} byte-identical`, apiSrc === webSrc);
}

// 3. old duplicated trees gone
for (const rel of ['app/api/src/rules/engine.js', 'app/web/src/lib/rules/engine.js']) {
  try {
    await stat(join(ROOT, rel));
    ok(`old duplicate gone: ${rel}`, false, 'file still exists');
  } catch {
    ok(`old duplicate gone: ${rel}`, true);
  }
}

// 4. lockfiles reference the new path
const apiLock = await readFile(join(ROOT, 'app/api/package-lock.json'), 'utf8');
const webLock = await readFile(join(ROOT, 'app/web/package-lock.json'), 'utf8');
ok('api lockfile → file:packages/rules', apiLock.includes('file:packages/rules') && !apiLock.includes('file:../../packages/rules'));
ok('web lockfile → file:packages/rules', webLock.includes('file:packages/rules') && !webLock.includes('file:../../packages/rules'));

// 5. installed symlinks resolve to local vendored copies
for (const svc of ['app/api', 'app/web']) {
  try {
    const rp = await realpath(join(ROOT, svc, 'node_modules/@einvoicecheck/rules'));
    const expected = join(ROOT, svc, 'packages/rules');
    ok(`${svc} node_modules symlink → vendored copy`, rp.replace(/\\/g, '/').toLowerCase() === expected.replace(/\\/g, '/').toLowerCase(), rp);
  } catch (e) {
    ok(`${svc} node_modules symlink`, false, e.message);
  }
}

console.log(failures === 0 ? '\nRESULT: ALL AD-HOC CHECKS PASSED' : `\nRESULT: ${failures} CHECK(S) FAILED`);
process.exit(failures === 0 ? 0 : 1);
