{"content": "#!/usr/bin/env node
/**
 * verify-compliance-assets.js
 *
 * Fails when a bundled PINT-AE resource differs from the compliance manifest.
 * Phase 1 gate: resources are immutable, attributable and hash-verified.
 *
 * Usage: node scripts/verify-compliance-assets.js
 * Exit 0 = all recorded files match the manifest SHA-256.
 * Exit 1 = a file is missing, or its hash differs (corruption / tamper / drift).
 *
 * The manifest records the schematron XSLT/SEF pair explicitly; codelist
 * hashes are stored in the per-tree .compliance-hashes.json (regenerated here).
 */
import { createHash } from 'node:crypto';
import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const API_ROOT = resolve(__dirname, '..');
const PINT_AE_DIR = join(API_ROOT, 'pint-ae');
const MANIFEST_PATH = join(API_ROOT, 'src/compliance/manifests/pint-ae-current.json');

const manifest = JSON.parse(readFileSync(MANIFEST_PATH, 'utf8'));

function sha256(file) {
  return createHash('sha256').update(readFileSync(file)).digest('hex');
}

let failures = 0;

// 1. Schematron files (recorded explicitly in the manifest)
const sch = manifest.resources.schematron;
for (const [name, meta] of Object.entries(sch)) {
  const p = join(PINT_AE_DIR, 'trn-invoice/schematron', name);
  if (!existsSync(p)) {
    console.error(`FAIL  missing: ${name}`);
    failures++;
    continue;
  }
  const actual = sha256(p);
  if (actual !== meta.sha256) {
    console.error(`FAIL  hash mismatch: ${name}\n  expected ${meta.sha256}\n  actual   ${actual}`);
    failures++;
  } else {
    console.log(`PASS  ${name}  (${meta.bytes} bytes, hash matches manifest)`);
  }
}

// 2. Codelists (all .gc under pint-ae; per-file hashes maintained here)
const codelistDir = join(PINT_AE_DIR, 'trn-invoice/codelist');
const hashPath = join(PINT_AE_DIR, '.compliance-hashes.json');
let prev = {};
if (existsSync(hashPath)) prev = JSON.parse(readFileSync(hashPath, 'utf8'));

const fs = await import('node:fs');
const gcFiles = fs.readdirSync(codelistDir).filter((f) => f.endsWith('.gc')).sort();
const current = {};
for (const f of gcFiles) {
  current[f] = sha256(join(codelistDir, f));
  if (prev[f] && prev[f] !== current[f]) {
    console.error(`FAIL  codelist hash changed: ${f}`);
    failures++;
  } else {
    console.log(`PASS  ${f}`);
  }
}
// Persist for drift detection on next run
writeFileSync(hashPath, JSON.stringify(current, null, 2) + '\n');

console.log(failures === 0
  ? `\nRESULT: all ${Object.keys(sch).length} schematron + ${gcFiles.length} codelist files verified`
  : `\nRESULT: ${failures} FAILURE(S) — resources drifted from manifest`);
process.exit(failures === 0 ? 0 : 1);
